import { tv } from "tailwind-variants";

const previewCard = tv({
  slots: {
    trigger: [
      "rounded-sm font-medium text-foreground underline underline-offset-2 transition-all duration-150 ease-default outline-none",
      "hover:text-foreground/90",
      "focus-visible:ring-2 focus-visible:ring-ring/50",
      "data-popup-open:text-foreground/80",
    ],
    portal: "",
    backdrop: "",
    positioner: "",
    popup: [
      "relative flex h-(--popup-height,auto) w-(--popup-width,auto) origin-(--transform-origin) flex-col rounded-md border border-border bg-popover text-popover-foreground shadow-md transition-[scale,opacity] duration-200 ease-default outline-none",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
    ],
    arrow: [
      "relative block h-1.5 w-3 overflow-clip",
      "before:absolute before:bottom-0 before:left-1/2 before:h-[calc(6px*sqrt(2))] before:w-[calc(6px*sqrt(2))] before:transform-[translate(-50%,50%)_rotate(45deg)] before:border before:border-border before:bg-popover before:content-['']",
      "data-[side=bottom]:-top-1.5",
      "data-[side=inline-end]:-inset-s-2.25 data-[side=inline-end]:-rotate-90",
      "data-[side=inline-start]:-inset-e-2.25 data-[side=inline-start]:rotate-90",
      "data-[side=left]:-right-2.25 data-[side=left]:rotate-90",
      "data-[side=right]:-left-2.25 data-[side=right]:-rotate-90",
      "data-[side=top]:-bottom-1.5 data-[side=top]:rotate-180",
    ],
    viewport: "",
    content: "flex flex-col p-3",
  },
});

export { previewCard };

"use client";

import { mergeProps, useDirection, useRender } from "@base-ui/react";
import { PreviewCard as BasePreviewCard } from "@base-ui/react/preview-card";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { previewCard } from "./preview-card.style";

const POSITIONER_SIDE_OFFSET = 8;

const createPreviewCardHandle = BasePreviewCard.createHandle;

function PreviewCard(props: BasePreviewCard.Root.Props) {
  return <BasePreviewCard.Root {...props} />;
}

function PreviewCardTrigger({
  className,
  ...props
}: BasePreviewCard.Trigger.Props) {
  return (
    <BasePreviewCard.Trigger
      data-slot="preview-card-trigger"
      className={mergeSlotClassName(previewCard().trigger, className)}
      {...props}
    />
  );
}

function PreviewCardPortal({
  className,
  ...props
}: BasePreviewCard.Portal.Props) {
  const direction = useDirection();

  return (
    <BasePreviewCard.Portal
      data-slot="preview-card-portal"
      className={mergeSlotClassName(previewCard().portal, className)}
      {...props}
      dir={direction}
    />
  );
}

function PreviewCardBackdrop({
  className,
  ...props
}: BasePreviewCard.Backdrop.Props) {
  return (
    <BasePreviewCard.Backdrop
      data-slot="preview-card-backdrop"
      className={mergeSlotClassName(previewCard().backdrop, className)}
      {...props}
    />
  );
}

function PreviewCardPositioner({
  className,
  sideOffset = POSITIONER_SIDE_OFFSET,
  ...props
}: BasePreviewCard.Positioner.Props) {
  return (
    <BasePreviewCard.Positioner
      data-slot="preview-card-positioner"
      className={mergeSlotClassName(previewCard().positioner, className)}
      sideOffset={sideOffset}
      {...props}
    />
  );
}

function PreviewCardPopup({
  className,
  ...props
}: BasePreviewCard.Popup.Props) {
  return (
    <BasePreviewCard.Popup
      data-slot="preview-card-popup"
      className={mergeSlotClassName(previewCard().popup, className)}
      {...props}
    />
  );
}

function PreviewCardArrow({
  className,
  ...props
}: BasePreviewCard.Arrow.Props) {
  return (
    <BasePreviewCard.Arrow
      data-slot="preview-card-arrow"
      className={mergeSlotClassName(previewCard().arrow, className)}
      {...props}
    />
  );
}

function PreviewCardViewport({
  className,
  ...props
}: BasePreviewCard.Viewport.Props) {
  return (
    <BasePreviewCard.Viewport
      data-slot="preview-card-viewport"
      className={mergeSlotClassName(previewCard().viewport, className)}
      {...props}
    />
  );
}

function PreviewCardContent({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div">) {
  const content = useRender({
    defaultTagName: "div",
    props: {
      ...mergeProps<"div">(
        { className: previewCard().content({ className }) },
        props,
      ),
      "data-slot": "preview-card-content",
    },
    render,
  });

  return content;
}

export {
  createPreviewCardHandle,
  PreviewCard,
  PreviewCardTrigger,
  PreviewCardPortal,
  PreviewCardBackdrop,
  PreviewCardPositioner,
  PreviewCardPopup,
  PreviewCardArrow,
  PreviewCardViewport,
  PreviewCardContent,
};
